import base64

data = ""

# Reversing for analysis
rev = data[::-1]
# If it starts with =, it might be reversed base64
if rev.endswith('='):
    print("Detected reversed-looking base64. Attempting reverse decode...")
    try:
        # Pad if needed
        d = rev
        missing_padding = len(d) % 4
        if missing_padding:
            d += '=' * (4 - missing_padding)
        decoded = base64.b64decode(d)
        with open("scratch/binary_output.bin", "wb") as f:
            f.write(decoded)
        print("Success! Decoded binary size:", len(decoded))
        
        # Check if it looks like a string after a shift/XOR
        # Let's try reversing the results or checking for common characters
        s = decoded.decode('utf-8', errors='ignore')
        print("First 100 bytes as string (ignored errors):", s[:100])
    except Exception as e:
        print("Error:", e)
